-- retention/purge-submission-ip-hashes
-- Blanks the visitor IP hash on submissions older than 30 days.
--
-- Parameters, with the example values used to render this file:
--   $1 = null
--
-- Generated by `pnpm db:queries` from lib/db/queries/retention.ts. Do not edit by hand.

update "submissions"
set "ip_hash" = $1
where ("submissions"."ip_hash" is not null
  and "submissions"."created_at" < now() - interval '30 days')
returning "id";
